import os, sys, json, time

def parse_seed_and_n(name):
    # Handles patterns like "seed=3_n=1000.json", "ks_seed=3_n=1000.json", "jb_seed=3_n=1000.json"
    try:
        core = name.split(".json")[0]
        if core.startswith("seed="):
            _, rest = core.split("seed=", 1)
            s_str, n_part = rest.split("_n=", 1)
            return int(s_str), int(n_part)
        if core.startswith("ks_seed="):
            _, rest = core.split("ks_seed=", 1)
            s_str, n_part = rest.split("_n=", 1)
            return int(s_str), int(n_part)
        if core.startswith("jb_seed="):
            _, rest = core.split("jb_seed=", 1)
            s_str, n_part = rest.split("_n=", 1)
            return int(s_str), int(n_part)
    except Exception:
        pass
    return None, None

def load_json(path):
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)

def main():
    lineage = "axiom"
    project = "rng_demo"
    base_dir = os.path.join("storage", lineage, "rng_runs")
    out_dir = os.path.join("storage", "shared", "agency_lab")
    os.makedirs(out_dir, exist_ok=True)
    out_path = os.path.join(out_dir, "axiom_rng_actions_v1.json")

    files = os.listdir(base_dir) if os.path.isdir(base_dir) else []
    per_seed = {}

    # Collect per-seed metrics (seed=...), KS (ks_seed=...), JB (jb_seed=...)
    for fn in files:
        if not fn.endswith(".json"):
            continue
        s, n = parse_seed_and_n(fn)
        if s is None:
            continue
        rec = per_seed.setdefault(s, {"n": n})
        try:
            j = load_json(os.path.join(base_dir, fn))
        except Exception:
            continue

        if fn.startswith("seed="):
            # metrics JSON
            rec["metrics"] = j.get("metrics", {})
        elif fn.startswith("ks_seed="):
            res = j.get("result", {})
            rec["ks"] = {"pvalue": res.get("pvalue"), "ks_stat": res.get("ks_stat"), "method": res.get("method")}
        elif fn.startswith("jb_seed="):
            res = j.get("result", {})
            rec["jb"] = {
                "pvalue": res.get("pvalue"),
                "jb_stat": res.get("jb_stat"),
                "skewness": res.get("skewness"),
                "kurtosis": res.get("kurtosis"),
                "method": res.get("method"),
            }

    # Optionally load aggregate summaries (v2, v4, v5) if present
    aggregates = {}
    for name in ("summary_v2.json", "summary_v4.json", "summary_v5.json"):
        p = os.path.join(base_dir, name)
        if os.path.exists(p):
            try:
                aggregates[name] = load_json(p)
            except Exception:
                pass

    # Build actions payload
    agents = {}
    actions = []
    for s, rec in sorted(per_seed.items()):
        agent_id = f"{lineage}_rng_seed_{s}"
        agents[agent_id] = {
            "description": f"{lineage} RNG run (seed={s}, n={rec.get('n')})",
            "project": project
        }
        # Generation action with summary metrics
        actions.append({
            "agent_id": agent_id,
            "action_type": "generate",
            "target": project,
            "metadata": {
                "seed": s,
                "n": rec.get("n"),
                "metrics": rec.get("metrics", {})
            }
        })
        # KS analysis action
        if "ks" in rec:
            actions.append({
                "agent_id": agent_id,
                "action_type": "analyze_ks",
                "target": project,
                "metadata": {
                    **rec["ks"],
                    "alpha": 0.05,
                    "pass": (rec["ks"].get("pvalue") is not None and rec["ks"]["pvalue"] >= 0.05)
                }
            })
        # JB analysis action
        if "jb" in rec:
            actions.append({
                "agent_id": agent_id,
                "action_type": "analyze_jb",
                "target": project,
                "metadata": {
                    **rec["jb"],
                    "alpha": 0.05,
                    "pass": (rec["jb"].get("pvalue") is not None and rec["jb"]["pvalue"] >= 0.05)
                }
            })

    # Aggregate action (optional, summarizing available aggregates)
    agg_meta = {}
    for k, v in aggregates.items():
        agg_meta[k] = v.get("aggregated", v)
    if agg_meta:
        actions.append({
            "agent_id": f"{lineage}_aggregator",
            "action_type": "aggregate",
            "target": project,
            "metadata": agg_meta
        })

    payload = {
        "schema": "agency_actions.v0.1-proposed",
        "source": "Axiom I",
        "lineage": lineage,
        "project": project,
        "generated_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "agents": agents,
        "actions": actions,
        "notes": "Maps Axiom RNG runs to generic agency actions (agent_id, action_type, target, metadata)."
    }

    with open(out_path, "w", encoding="utf-8") as f:
        json.dump(payload, f, ensure_ascii=False, indent=2)

    print("WROTE", out_path)
    print("COUNTS", json.dumps({"agents": len(agents), "actions": len(actions)}))
    return 0

if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print("ERROR", str(e))
        raise SystemExit(1)
